fn add_digits(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut result = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry = 0u8;
    let mut i = 0;

    while i < a.len() || i < b.len() {
        let sum = carry
            + a.get(i).copied().unwrap_or(0)
            + b.get(i).copied().unwrap_or(0);
        result.push(sum % 10);
        carry = sum / 10;
        i += 1;
    }
    if carry != 0 {
        result.push(carry);
    }
    result
}

fn main() {
    let n: usize = std::env::args()
        .nth(1)
        .expect("missing N")
        .parse()
        .expect("N must be a non-negative integer");

    let (mut a, mut b) = (vec![1u8], vec![1u8]);
    for _ in 0..n {
        let next = add_digits(&a, &b);
        a = b;
        b = next;
    }

    let output: String = a
        .iter()
        .rev()
        .map(|digit| (b'0' + *digit) as char)
        .collect();
    println!("{}", output);
}

