#include <iostream>
#include <string>
#include <vector>

std::vector<unsigned> add_digits(const std::vector<unsigned> &a,
                                 const std::vector<unsigned> &b) {
    const std::size_t size = a.size() > b.size() ? a.size() : b.size();
    std::vector<unsigned> result;
    result.reserve(size + 1);
    unsigned carry = 0;

    for (std::size_t i = 0; i < size; ++i) {
        const unsigned left = i < a.size() ? a[i] : 0;
        const unsigned right = i < b.size() ? b[i] : 0;
        const unsigned sum = carry + left + right;
        result.push_back(sum % 10);
        carry = sum / 10;
    }
    if (carry != 0) {
        result.push_back(carry);
    }
    return result;
}

int main(int argc, char **argv) {
    const unsigned long long n = std::stoull(argv[1]);
    std::vector<unsigned> a(1, 1);
    std::vector<unsigned> b(1, 1);

    for (unsigned long long i = 0; i < n; ++i) {
        std::vector<unsigned> next = add_digits(a, b);
        a = b;
        b = next;
    }

    for (auto it = a.rbegin(); it != a.rend(); ++it) {
        std::cout << *it;
    }
    std::cout << '\n';
    return 0;
}

